#include <algorithm>
#include <cmath>
#include <cstdint>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <iterator>
#include <map>
#include <set>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>
#ifdef _WIN32
#include "../memory/win_sqlite_memory_api.hpp"
#else
#include <sqlite3.h>
#endif
namespace fs=std::filesystem;
struct Node {std::string file,name,statement;int line=0;std::set<std::string> tags;};
struct Path {int a=0,b=0,c=0,score=0;std::string evidence;};
static std::string quoted(const std::string& s){std::string o="\"";for(char c:s){if(c=='\"')o+='\"';if(c=='\r'||c=='\n')o+=' ';else o+=c;}return o+'\"';}
static bool token(const std::string& s,const std::string& t){size_t pos=0;while((pos=s.find(t,pos))!=std::string::npos){const size_t end=pos+t.size();auto ident=[](unsigned char c){return (c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||c=='_';};if((pos==0||!ident(static_cast<unsigned char>(s[pos-1])))&&(end==s.size()||!ident(static_cast<unsigned char>(s[end]))))return true;pos=end;}return false;}
static std::set<std::string> tags(const std::string& s){std::set<std::string> r;for(const std::string t:{"Nat","Int","Fin","ZMod","Bool","List","Array","Vector","Real","Rat","Complex","Matrix","Set","Ring","Group","Monoid","Equiv","Hom"})if(token(s,t))r.insert("type:"+t);for(const auto& p:std::vector<std::pair<std::string,std::string>>{{"+","op:add"},{"*","op:mul"},{"^","op:pow"},{"=","rel:eq"},{"≤","rel:le"},{"→","rel:implies"},{"∧","rel:and"},{"%","op:mod"}})if(s.find(p.first)!=std::string::npos)r.insert(p.second);return r;}
static std::set<std::string> common(const Node& a,const Node& b){std::set<std::string> c;std::set_intersection(a.tags.begin(),a.tags.end(),b.tags.begin(),b.tags.end(),std::inserter(c,c.end()));return c;}
static std::string combine(const std::set<std::string>& s){std::string r;for(const auto& x:s){if(!r.empty())r+=';';r+=x;}return r;}
static std::vector<Node> readSource(const fs::path& file,int limit,const std::string& filter){if(!fs::is_regular_file(file))throw std::runtime_error("Source DB not found: "+file.string());sqlite3* db=nullptr;int rc=sqlite3_open_v2(file.string().c_str(),&db,SQLITE_OPEN_READONLY,nullptr);if(rc!=SQLITE_OK){std::string e=db?sqlite3_errmsg(db):"sqlite open failed";if(db)sqlite3_close(db);throw std::runtime_error(e);}sqlite3_stmt* stmt=nullptr;try{if(sqlite3_exec(db,"PRAGMA query_only=ON",nullptr,nullptr,nullptr)!=SQLITE_OK)throw std::runtime_error(sqlite3_errmsg(db));const char* sql="SELECT file,line,name,statement FROM declarations WHERE statement IS NOT NULL AND length(statement)>0 AND (?1='' OR file LIKE ?2) ORDER BY file,line LIMIT ?3";if(sqlite3_prepare_v2(db,sql,-1,&stmt,nullptr)!=SQLITE_OK)throw std::runtime_error(sqlite3_errmsg(db));const std::string pattern="%"+filter+"%";sqlite3_bind_text(stmt,1,filter.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(stmt,2,pattern.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_int(stmt,3,limit);std::vector<Node> v;auto get=[&](int i){const auto* c=sqlite3_column_text(stmt,i);return c?std::string(reinterpret_cast<const char*>(c)):std::string();};int status=SQLITE_ROW;while((status=sqlite3_step(stmt))==SQLITE_ROW){Node n;n.file=get(0);n.line=sqlite3_column_int(stmt,1);n.name=get(2);n.statement=get(3);n.tags=tags(n.statement);v.push_back(std::move(n));}if(status!=SQLITE_DONE)throw std::runtime_error(sqlite3_errmsg(db));sqlite3_finalize(stmt);sqlite3_close(db);return v;}catch(...){if(stmt)sqlite3_finalize(stmt);sqlite3_close(db);throw;}}
static std::vector<Path> paths(const std::vector<Node>& n,size_t maxPaths){std::map<std::string,std::vector<int>> inv;for(size_t i=0;i<n.size();++i)for(const auto& t:n[i].tags)inv[t].push_back(static_cast<int>(i));std::vector<std::set<int>> adj(n.size());for(const auto& kv:inv){const auto& ids=kv.second;if(ids.size()>96)continue;for(size_t a=0;a<ids.size();++a)for(size_t b=a+1;b<ids.size();++b){adj[static_cast<size_t>(ids[a])].insert(ids[b]);adj[static_cast<size_t>(ids[b])].insert(ids[a]);}}std::vector<Path> p;std::set<std::string> seen;for(size_t b=0;b<n.size()&&p.size()<maxPaths;++b){std::vector<int> ne(adj[b].begin(),adj[b].end());if(ne.size()>48)ne.resize(48);for(size_t i=0;i<ne.size()&&p.size()<maxPaths;++i)for(size_t j=i+1;j<ne.size()&&p.size()<maxPaths;++j){int a=ne[i],c=ne[j];if(adj[static_cast<size_t>(a)].count(c))continue;auto l=common(n[static_cast<size_t>(a)],n[b]);auto r=common(n[b],n[static_cast<size_t>(c)]);if(l.empty()||r.empty())continue;int lo=std::min(a,c),hi=std::max(a,c);std::string key=std::to_string(lo)+":"+std::to_string(b)+":"+std::to_string(hi);if(!seen.insert(key).second)continue;Path q;q.a=lo;q.b=static_cast<int>(b);q.c=hi;q.score=static_cast<int>(l.size()+r.size());q.evidence=combine(l)+" | "+combine(r);p.push_back(std::move(q));}}std::stable_sort(p.begin(),p.end(),[](const Path& a,const Path& b){return a.score>b.score;});return p;}
static uint32_t step(uint32_t state,uint32_t input,int family){switch(family%5){case 0:return (state+input*3u)%65521u;case 1:return (state*17u+input)%65521u;case 2:return (state^input)%65521u;case 3:return (state+input)%65521u;default:return (state*state+input)%65521u;}}
static double eval(int family,int seed){uint32_t a=0,b=0;double loss=0;for(int k=0;k<256;++k){uint32_t x=static_cast<uint32_t>((k*37+seed*101)%65521);a=step(a,x,family);b=step(b,x,3);const double d=static_cast<double>(a)-static_cast<double>(b);loss+=d*d;}return loss/256.0;}
static std::string formula(int family){switch(family%5){case 0:return "(state+input*3u)%65521u";case 1:return "(state*17u+input)%65521u";case 2:return "(state^input)%65521u";case 3:return "(state+input)%65521u";default:return "(state*state+input)%65521u";}}
static void program(const fs::path& dir,int family,const Path& p,const std::vector<Node>& n){fs::create_directories(dir);std::ofstream h(dir/"candidate.hpp");h<<"#pragma once\n#include <cstdint>\ninline std::uint32_t candidate_step(std::uint32_t state,std::uint32_t input) noexcept{return "<<formula(family)<<";}\n";std::ofstream m(dir/"main.cpp");m<<"#include \"candidate.hpp\"\n#include <cstdint>\n#include <fstream>\n#include <iostream>\n#include <string>\nint main(int argc,char**argv){if(argc==2&&std::string(argv[1])==\"--selftest\"){if(candidate_step(0,1)!="<<step(0,1,family)<<"u)return 1;std::cout<<\"SELFTEST PASS\\n\";return 0;}if(argc!=2)return 2;std::ofstream out(argv[1]);if(!out)return 3;out<<\"index,input,state\\n\";std::uint32_t s=0;for(std::uint32_t i=0;i<256u;++i){s=candidate_step(s,i);out<<i<<','<<i<<','<<s<<'\\n';}return out?0:4;}\n";std::ofstream c(dir/"CMakeLists.txt");c<<"cmake_minimum_required(VERSION 3.21)\nproject(MRE_v10_candidate LANGUAGES CXX)\nadd_executable(discovered_app main.cpp)\ntarget_compile_features(discovered_app PRIVATE cxx_std_20)\nif(MSVC)\n target_compile_options(discovered_app PRIVATE /W4 /WX /permissive- /EHsc)\nelse()\n target_compile_options(discovered_app PRIVATE -Wall -Wextra -Wpedantic -Werror)\nendif()\n";std::ofstream prov(dir/"PROVENANCE.md");prov<<"# Source-derived hypothesis – NOT a formal Lean translation\n\n";for(int id:{p.a,p.b,p.c})prov<<"- "<<n[static_cast<size_t>(id)].name<<" ("<<n[static_cast<size_t>(id)].file<<":"<<n[static_cast<size_t>(id)].line<<")\n";prov<<"\nThe generated recurrence is a numerical experiment inspired by graph motifs. No theorem proves it equivalent to any Lean declaration.\n";}
static int run(const fs::path& source,const fs::path& dir,int limit,int maxApps,const std::string& filter){auto n=readSource(source,limit,filter);auto p=paths(n,20000);fs::create_directories(dir);std::ofstream edges(dir/"paths.csv");edges<<"source,bridge,target,score,evidence,lean_status\n";for(const auto& x:p)edges<<quoted(n[static_cast<size_t>(x.a)].name)<<','<<quoted(n[static_cast<size_t>(x.b)].name)<<','<<quoted(n[static_cast<size_t>(x.c)].name)<<','<<x.score<<','<<quoted(x.evidence)<<",NOT_PROVED\n";std::ofstream scores(dir/"evaluation.csv");scores<<"app,path_index,family,validation_mse,holdout_mse,baseline_holdout_mse,verdict\n";int made=0;for(size_t i=0;i<p.size()&&made<maxApps;++i){const auto& path=p[i];int family=(path.a+path.b+path.c)%5;double valid=eval(family,11),holdout=eval(family,73),baseline=eval(3,73);const std::string verdict=holdout<baseline?"DIFFERS_FROM_BASELINE_NOT_UTILITY":"NO_GAIN";if(made<maxApps){auto app=dir/"applications"/("application_"+std::to_string(made+1));program(app,family,path,n);scores<<made+1<<','<<i<<','<<family<<','<<valid<<','<<holdout<<','<<baseline<<','<<verdict<<'\n';++made;}}std::ofstream report(dir/"RESEARCH_REPORT.md");report<<"# MRE v10 Multi-Relation Research\n\n- Source database: opened **READ_ONLY**\n- Sampled declarations: "<<n.size()<<"\n- Two-edge graph paths: "<<p.size()<<"\n- Generated runnable candidates: "<<made<<"\n\n## Evidence levels\n\nGraph paths are based on shared mathematical tokens, not verified type composability. Lean proof status: NOT_PROVED. Generated kernels are independent hypotheses. Numeric evaluation uses a synthetic stream and reports differences from a simple baseline, **not practical utility**. Formal proof, external datasets, repeated holdouts and new domain tests remain future work.\n";if(!edges||!scores||!report)throw std::runtime_error("Report IO failed");std::cout<<"V10_PASS declarations="<<n.size()<<" paths="<<p.size()<<" generated="<<made<<" source=READ_ONLY formal=NOT_PROVED destination="<<dir.string()<<'\n';return 0;}
int main(int argc,char** argv){try{if(argc==2&&std::string(argv[1])=="selftest"){Node a{"f", "a","Nat + Real",1,tags("Nat + Real")},b{"f","b","Nat + Bool",2,tags("Nat + Bool")},c{"f","c","Bool * Int",3,tags("Bool * Int")};auto p=paths({a,b,c},10);if(p.empty()||step(0,1,1)!=1u)throw std::runtime_error("selftest failure");std::cout<<"MULTI_RELATION_V10_SELFTEST PASS\n";return 0;}if(argc<3||argc>6){std::cerr<<"usage: executable source.sqlite output [limit=1000] [apps=4] [file-filter]\n";return 2;}return run(argv[1],argv[2],argc>=4?std::stoi(argv[3]):1000,argc>=5?std::stoi(argv[4]):4,argc==6?argv[5]:"");}catch(const std::exception& e){std::cerr<<"V10_ERROR "<<e.what()<<'\n';return 1;}}
